package com.alpharip.staffmod.BuildTimelapse.effects;
import java.io.*;import java.nio.file.*;import java.util.Properties;
/** Versioned, local-only persistence for one project's visual effects profile. */
public final class FileEffectsProfileStore {
 private final File root;
 public FileEffectsProfileStore(File root){if(root==null)throw new IllegalArgumentException("root");this.root=root;}
 public void save(String projectId,VisualEffectsProfile profile)throws IOException{validateId(projectId);if(profile==null)throw new IllegalArgumentException("profile");ensureRoot();Properties p=new Properties();p.setProperty("format","1");p.setProperty("hideHud",Boolean.toString(profile.isHideHud()));p.setProperty("hideHand",Boolean.toString(profile.isHideHand()));p.setProperty("hideParticles",Boolean.toString(profile.isHideParticles()));p.setProperty("fov",Float.toString(profile.getFov()));writeAtomically(new File(root,projectId+".effects"),p);}
 public VisualEffectsProfile load(String projectId)throws IOException{validateId(projectId);File f=new File(root,projectId+".effects");if(!f.isFile())throw new FileNotFoundException(f.toString());Properties p=new Properties();try(InputStream in=new BufferedInputStream(new FileInputStream(f))){p.load(in);}if(!"1".equals(p.getProperty("format")))throw new IOException("Unsupported effects profile format");try{VisualEffectsProfile v=new VisualEffectsProfile();v.setHideHud(booleanValue(p,"hideHud"));v.setHideHand(booleanValue(p,"hideHand"));v.setHideParticles(booleanValue(p,"hideParticles"));v.setFov(Float.parseFloat(required(p,"fov")));return v;}catch(IllegalArgumentException e){throw new IOException("Invalid effects profile for "+projectId,e);}}
 private void ensureRoot()throws IOException{if((!root.exists()&&!root.mkdirs())||!root.isDirectory())throw new IOException("Cannot create effects profile directory");}
 private static void writeAtomically(File target,Properties p)throws IOException{File tmp=new File(target.getParentFile(),target.getName()+".tmp");try(OutputStream o=new BufferedOutputStream(new FileOutputStream(tmp))){p.store(o,"Build Timelapse effects profile");}try{Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{if(tmp.exists()&&!tmp.delete())tmp.deleteOnExit();}}
 private static boolean booleanValue(Properties p,String key)throws IOException{String value=required(p,key);if(!"true".equalsIgnoreCase(value)&&!"false".equalsIgnoreCase(value))throw new IOException("Invalid boolean effects property: "+key);return Boolean.parseBoolean(value);}
 private static String required(Properties p,String k)throws IOException{String v=p.getProperty(k);if(v==null)throw new IOException("Missing effects property: "+k);return v;}
 private static void validateId(String id)throws IOException{if(id==null||!id.matches("[A-Za-z0-9_-]{1,80}"))throw new IOException("Invalid project id");}
}
